// Get canvas and context
const canvas = document.getElementById("neonCanvas");
const ctx = canvas.getContext("2d");

// Set canvas size to window dimensions
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

// Neon Line constructor
function createNeonLine() {
  const neonLine = {
    posX: -100, // Start off-screen to the left
    posY: Math.random() * canvas.height * 2 - 200, // Random Y position
    lineLength: Math.random() * 100 + 50, // Random length between 50-150
    moveSpeed: Math.random() * 1 + 2, // Speed between 2-3
    lineAngle: Math.PI * 0.1, // Fixed diagonal angle
    colorHue: Math.random() * 360, // Random starting hue
    thickness: Math.random() * 5 + 2, // Thickness between 2-7
    startDelay: Math.random() * 2000, // Delay before moving (0-2s)
    creationTime: Date.now(), // Timestamp of creation
  };

  // Draw the neon line with glow effect
  neonLine.draw = function () {
    ctx.beginPath();
    ctx.moveTo(this.posX, this.posY);
    ctx.lineTo(
      this.posX + Math.cos(this.lineAngle) * this.lineLength,
      this.posY + Math.sin(this.lineAngle) * this.lineLength
    );

    const color = `hsl(${this.colorHue}, 100%, 50%)`; // Bright, saturated color
    ctx.strokeStyle = color;
    ctx.lineWidth = this.thickness;
    ctx.lineCap = "round"; // Smooth line ends
    ctx.shadowBlur = 20; // Neon glow effect
    ctx.shadowColor = color;
    ctx.stroke();
  };

  // Update line position and hue
  neonLine.update = function () {
    const currentTime = Date.now();
    if (currentTime - this.creationTime < this.startDelay) return; // Wait for delay

    this.posX += Math.cos(this.lineAngle) * this.moveSpeed; // Move horizontally
    this.posY += Math.sin(this.lineAngle) * this.moveSpeed; // Move vertically
    this.colorHue = (this.colorHue + 1) % 360; // Cycle hue (0-360)

    // Reset if line moves off-screen
    if (
      this.posX > canvas.width + 100 ||
      this.posY > canvas.height ||
      this.posY < -200
    ) {
      this.reset();
    }
  };

  // Reset line properties for reuse
  neonLine.reset = function () {
    this.posX = -100; // Back to left edge
    this.posY = Math.random() * canvas.height * 2 - 200; // New random Y
    this.lineLength = Math.random() * 100 + 50; // New random length
    this.moveSpeed = Math.random() * 1 + 2; // New random speed
    this.lineAngle = Math.PI * 0.1; // Fixed angle
    this.colorHue = Math.random() * 360; // New random hue
    this.thickness = Math.random() * 5 + 2; // New random thickness
    this.creationTime = Date.now(); // Reset timestamp
    this.startDelay = Math.random() * 2000; // New random delay
  };

  return neonLine;
}

// Initialize neon lines
const NEON_LINES = [];
const LINE_COUNT = 100;
for (let i = 0; i < LINE_COUNT; i++) {
  NEON_LINES.push(createNeonLine());
}

// Background stars
const STARS = [];
const STAR_COUNT = 100;
for (let i = 0; i < STAR_COUNT; i++) {
  STARS.push({
    posX: Math.random() * canvas.width, // Random X position
    posY: Math.random() * canvas.height, // Random Y position
    radius: Math.random() * 2 + 1, // Size between 1-3
    opacity: Math.random(), // Random initial opacity
  });
}

// Draw solid background
function drawBackground() {
  ctx.fillStyle = "#2c2c2c"; // Dark gray base
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

// Draw gradient background
function drawGradientBackground() {
  const gradient = ctx.createLinearGradient(0, 0, canvas.width, canvas.height);
  gradient.addColorStop(0, "#2c2c2c"); // Dark gray
  gradient.addColorStop(0.33, "#4b0082"); // Indigo
  gradient.addColorStop(0.66, "#8a2be2"); // Purple
  gradient.addColorStop(1, "#ff00ff"); // Magenta

  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

// Draw twinkling stars
function drawStars() {
  STARS.forEach((star) => {
    ctx.beginPath();
    ctx.arc(star.posX, star.posY, star.radius, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(255, 255, 255, ${star.opacity})`; // White with varying opacity
    ctx.fill();
  });
}

// Update star opacity for twinkling effect
function updateStars() {
  STARS.forEach((star) => {
    star.opacity += (Math.random() - 0.5) * 0.02; // Randomly adjust opacity
    star.opacity = Math.max(0, Math.min(1, star.opacity)); // Clamp between 0-1
  });
}

// Full animation loop with background and neon lines
function animateScene() {
  drawGradientBackground(); // Draw gradient first
  drawStars(); // Draw stars on top
  updateStars(); // Update star twinkling

  NEON_LINES.forEach((line) => {
    line.draw(); // Draw each neon line
    line.update(); // Update its position and hue
  });

  requestAnimationFrame(animateScene); // Queue next frame
}

// Start the animation
animateScene();
